        Ok(())
    }
    #[tokio::test]
    async fn full_pending_wal_waits_for_checkpoint_instead_of_acknowledging_missing_data()
    -> Result<()> {
        let t = tempfile::tempdir()?;
        let mut c = config(&t);
        c.max_pending_mib = 3;
