        assert!(!task.is_finished());
        e.checkpoint().await?;
        tokio::time::timeout(std::time::Duration::from_secs(2), task).await???;
        assert_eq!(e.read(2 * 1024 * 1024, PAGE).await?, vec![2; PAGE]);
