use crate::config::Config;
use anyhow::{Context, Result, ensure};
use bytes::Bytes;
use fs2::FileExt as _;
use object_store::{
    ObjectStore, ObjectStoreExt, PutMode, PutOptions, UpdateVersion, aws::AmazonS3Builder,
    local::LocalFileSystem, path::Path,
};
use sha2::{Digest, Sha256};
use std::{fs::OpenOptions, ops::Range, path::PathBuf, sync::Arc};

#[derive(Clone)]
pub struct Store {
    pub inner: Arc<dyn ObjectStore>,
    prefix: String,
    root: Option<PathBuf>,
}
impl Store {
    pub fn new(c: &Config) -> Result<Self> {
        if let Some(dir) = c.store.strip_prefix("file://") {
            ensure!(dir.starts_with('/'), "file store must be absolute");
            std::fs::create_dir_all(dir)?;
            Ok(Self {
                inner: Arc::new(LocalFileSystem::new_with_prefix(dir)?),
                prefix: String::new(),
                root: Some(std::fs::canonicalize(dir)?),
            })
        } else {
            let rest = c
                .store
                .strip_prefix("s3://")
                .context("store must start with s3:// or file://")?;
            let (bucket, prefix) = rest
                .split_once('/')
                .context("S3 requires a dedicated nonempty prefix")?;
            ensure!(
                !bucket.is_empty() && !prefix.trim_matches('/').is_empty(),
                "empty S3 bucket/prefix"
            );
            let mut b = AmazonS3Builder::from_env()
                .with_bucket_name(bucket)
                .with_region(&c.region)
                .with_virtual_hosted_style_request(false);
            if let Some(e) = &c.endpoint {
                b = b.with_endpoint(e);
            }
            Ok(Self {
                inner: Arc::new(b.build()?),
                prefix: prefix.trim_matches('/').to_owned(),
                root: None,
            })
        }
    }
    pub fn path(&self, key: &str) -> Path {
        Path::from(if self.prefix.is_empty() {
            key.to_owned()
        } else {
            format!("{}/{key}", self.prefix)
        })
    }
    pub async fn get(&self, key: &str) -> Result<Bytes> {
        Ok(self.inner.get(&self.path(key)).await?.bytes().await?)
    }
    pub async fn range(&self, key: &str, range: Range<u64>) -> Result<Bytes> {
        Ok(self.inner.get_range(&self.path(key), range).await?)
    }
    pub async fn immutable(&self, key: &str, bytes: Bytes) -> Result<()> {
        // UUID object names are never reused for different contents. Retrying an upload is idempotent.
        if let Some(root) = &self.root {
            let path = root.join(key);
            let parent = path.parent().unwrap();
            let mut missing = Vec::new();
            let mut dir = parent;
            while !dir.exists() {
                missing.push(dir.to_path_buf());
                dir = dir.parent().context("invalid store path")?;
            }
            for dir in missing.into_iter().rev() {
                std::fs::create_dir(&dir)?;
                crate::wal::sync_dir(dir.parent().unwrap())?;
            }
            crate::wal::atomic(&path, &bytes)?;
            return Ok(());
        }
        self.inner.put(&self.path(key), bytes.into()).await?;
        Ok(())
    }
    pub async fn head(&self) -> Result<Option<(Bytes, UpdateVersion)>> {
        if let Some(root) = &self.root {
            return match std::fs::read(root.join("HEAD")) {
                Ok(b) => {
                    let v = UpdateVersion {
                        e_tag: Some(hex::encode(Sha256::digest(&b))),
                        version: None,
                    };
                    Ok(Some((b.into(), v)))
                }
                Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(None),
                Err(e) => Err(e.into()),
            };
        }
        match self.inner.get(&self.path("HEAD")).await {
            Ok(r) => {
                let v = UpdateVersion {
                    e_tag: r.meta.e_tag.clone(),
                    version: r.meta.version.clone(),
                };
                Ok(Some((r.bytes().await?, v)))
            }
            Err(object_store::Error::NotFound { .. }) => Ok(None),
            Err(e) => Err(e.into()),
        }
    }
    pub async fn cas(&self, bytes: Bytes, version: Option<UpdateVersion>) -> Result<UpdateVersion> {
        if let Some(root) = &self.root {
            let f = OpenOptions::new()
                .create(true)
                .truncate(false)
                .read(true)
                .write(true)
                .open(root.join(".HEAD.lock"))?;
            f.lock_exclusive()?;
            let current = self.head().await?;
            match (version, current) {
                (None, None) => {}
                (Some(expected), Some((_, actual))) => ensure!(
                    expected.e_tag == actual.e_tag,
                    "local HEAD conditional update conflict"
                ),
                _ => anyhow::bail!("local HEAD conditional create/update conflict"),
            }
            crate::wal::atomic(&root.join("HEAD"), &bytes)?;
            return Ok(UpdateVersion {
                e_tag: Some(hex::encode(Sha256::digest(&bytes))),
                version: None,
            });
        }
        let r = self
            .inner
            .put_opts(
                &self.path("HEAD"),
                bytes.into(),
                PutOptions {
                    mode: version.map_or(PutMode::Create, PutMode::Update),
                    ..Default::default()
                },
            )
            .await?;
        Ok(UpdateVersion {
            e_tag: r.e_tag,
            version: r.version,
        })
    }
}

src/ublk.rs.content:
//! Experimental ublk transport. Copies are retained; FLUSH and FUA are honored.
use crate::engine::Engine;
use anyhow::{Result, ensure};
use libublk::{BufDesc, UblkFlags, ctrl::UblkCtrlBuilder, helpers::IoBuf, io::UblkDev};
use std::sync::Arc;

pub fn delete(id: i32) -> Result<()> {
    ensure!(id >= 0, "explicit device id required");
    let ctrl = libublk::ctrl::UblkCtrl::new_simple(id)?;
    ensure!(
        ctrl.get_target_type_from_json()? == "infinidisk2-experimental",
        "device is not an InfiniDisk2 experimental target"
    );
    ctrl.del_dev()?;
    Ok(())
}
pub fn serve(
    engine: Arc<Engine>,
    handle: tokio::runtime::Handle,
    id: i32,
    queues: u16,
) -> Result<()> {
    ensure!(
        id >= 0 && (1..=8).contains(&queues),
        "invalid ublk id/queue count"
    );
    let ctrl = UblkCtrlBuilder::default()
        .name("infinidisk2-experimental")
        .id(id)
        .nr_queues(queues)
        .depth(32)
        .io_buf_bytes(1024 * 1024)
        .dev_flags(UblkFlags::UBLK_DEV_F_ADD_DEV)
        .build()?;
    let size = engine.identity.size;
    ctrl.run_target(
        move |dev: &mut UblkDev| {
            dev.tgt.dev_size = size;
            dev.tgt.params = libublk::sys::ublk_params {
                types: libublk::sys::UBLK_PARAM_TYPE_BASIC,
                basic: libublk::sys::ublk_param_basic {
                    attrs: libublk::sys::UBLK_ATTR_VOLATILE_CACHE,
                    logical_bs_shift: 9,
                    physical_bs_shift: 12,
                    io_opt_shift: 12,
                    io_min_shift: 9,
                    max_sectors: dev.dev_info.max_io_buf_bytes >> 9,
                    dev_sectors: size >> 9,
                    ..Default::default()
                },
                ..Default::default()
            };
            Ok(())
        },
        move |qid, dev| {
            let engine = engine.clone();
            let handle = handle.clone();
            let result = libublk::UblkRuntime::run_io_tasks(dev, qid, move |q, tag| {
                let engine = engine.clone();
                let handle = handle.clone();
                async move {
                    let mut buf = IoBuf::<u8>::new(q.dev().dev_info.max_io_buf_bytes as usize);
                    q.submit_io_prep_cmd(tag, BufDesc::Slice(buf.as_slice()), 0, Some(&buf))
                        .await?;
                    loop {
                        let iod = q.get_iod(tag);
                        let op = iod.op_flags & 0xff;
                        let fua = iod.op_flags & libublk::sys::UBLK_IO_F_FUA != 0;
                        let offset = iod.start_sector << 9;
                        let len = (iod.nr_sectors as usize) << 9;
                        let e = engine.clone();
                        let input = if op == libublk::sys::UBLK_IO_OP_WRITE {
                            buf.as_slice()[..len].to_vec()
                        } else {
                            Vec::new()
                        };
                        let result = handle
                            .spawn(async move {
                                let b = match op {
                                    libublk::sys::UBLK_IO_OP_READ => e.read(offset, len).await?,
                                    libublk::sys::UBLK_IO_OP_WRITE => {
                                        e.write(offset, &input).await?;
                                        if fua {
                                            e.flush().await?;
                                        }
                                        Vec::new()
                                    }
                                    libublk::sys::UBLK_IO_OP_FLUSH => {
                                        e.flush().await?;
                                        Vec::new()
                                    }
                                    _ => anyhow::bail!("unsupported ublk op {op}"),
                                };
                                Ok::<_, anyhow::Error>(b)
                            })
                            .await;
                        let res = match result {
                            Ok(Ok(b)) => {
                                if op == libublk::sys::UBLK_IO_OP_READ {
                                    buf.as_mut_slice()[..b.len()].copy_from_slice(&b);
                                }
                                if op == libublk::sys::UBLK_IO_OP_FLUSH {
                                    0
                                } else {
                                    len as i32
                                }
                            }
                            other => {
                                tracing::error!(error=?other,"ublk request failed");
                                -libc::EIO
                            }
                        };
                        q.submit_io_commit_cmd(tag, BufDesc::Slice(buf.as_slice()), res)
                            .await?;
                    }
                }
            });
            if let Err(err) = result {
                tracing::error!(error=%err,"ublk queue stopped");
            }
        },
        move |ctrl| {
            ctrl.dump();
        },
    )?;
    Ok(())
}

